// docs/geo/household_hist_real.json is what the page's path produces today: regenerated by
// household_hist_real.js's own render and compared byte for byte.
"use strict";
const test = require("node:test"), assert = require("node:assert"), fs = require("node:fs");
const { render, OUT, COMMAND } = require("./household_hist_real.js");

test("household_hist_real.json is current", () => {
  assert.ok(render(null) === fs.readFileSync(OUT, "utf8"), `docs/geo/household_hist_real.json is stale: run ${COMMAND}`);
});
